class Poll:
    def __init__(self, question: str) -> None:
        self.question = question
        self.options = []  # list of option names, in insertion order
        self.votes = {}    # voter -> option
        self.counts = {}   # option -> vote count

    def add_option(self, option: str) -> None:
        if option in self.counts:
            raise ValueError(f"Option already exists: {option}")
        self.options.append(option)
        self.counts[option] = 0

    def vote(self, voter: str, option: str) -> None:
        if voter in self.votes:
            raise ValueError(f"Voter already voted: {voter}")
        if option not in self.counts:
            raise ValueError(f"Unknown option: {option}")
        self.votes[voter] = option
        self.counts[option] += 1

    def results(self) -> dict[str, int]:
        return dict(self.counts)

    def winner(self) -> str | None:
        if len(self.votes) < 3:
            return None
        best = None
        best_count = -1
        # Iterate in insertion order; use >= so later options win ties.
        for option in self.options:
            c = self.counts[option]
            if c >= best_count:
                best = option
                best_count = c
        return best
```

